# The Flash player's display manager, contexts, sprite nodes, variables and remote function calls. Each mutant's text runs from the head of its function to the text changed, so that it occurs once.
# Dropped as equivalent, each with its reason:
#   * GotoFrame negative: a negative frame fails the unsigned comparison with the count right after it.
#   * Get no room: with room but no values, Find gives the undefined value, which is what the no-room branch copies; no room with values cannot be.
#   * ChildAtDepth stop: children are sorted by depth, so after the first at least as deep none can be equal.
#   * AddChild depth signed: depths come from 16-bit tag fields, so signed and unsigned order agree.
#   * FlushPending prev: every pending node is taken off and added to the children, which sets its prev.
#   * FindChild self: with matchSelf 0 no caller reads what found holds.
#   * TargetPath root: the terminator the mutant writes at the root is overwritten by the '/' its child writes next; GetProperty never asks the root itself.
#   * ExecuteScripts dead: a node's state is 1 or 2 once it is in a tree; -1 only before Init.
#   * SetTarget fallback: ResolvePath finds only nodes in children lists, which are alive, or a root, which is what the fallback gives.
#   * Construct clear: the value's constructor (0x00020A50), just run, sets every field Clear sets; compared after construction over three fills.
#   * RemoveAll new head: every child taken off goes first among the dead nodes, which sets its prev to null; the stale prev is never read.
#   * GotoFrameByExpression empty: an empty frame text counts as all digits and goes to atoi("") - 1, -1, which GotoFrame ignores.
import os
import sys

_SRC = os.path.join(os.path.dirname(os.path.abspath(sys._getframe().f_code.co_filename)), "..", "..", "..", "src", "at")
D = "AtFpDisplay.cpp"
_cache = {}


def _text(f):
    if f not in _cache:
        with open(os.path.join(_SRC, f), encoding="utf-8") as h:
            _cache[f] = h.read()
    return _cache[f]


def m(name, head, old, new, f=D):
    """A mutant replacing the first `old` after the function head `head`."""
    s = _text(f)
    a = s.index(head)
    b = s.index(old, a)
    text = s[a:b + len(old)]
    return (name, f, text, text[:len(text) - len(old)] + new)


